import AppKit

extension Tracker {
    func openPatternCopy(){let source=project.selected;copyTarget=(1..<128).map{(source+$0)%128}.first(where:{project.patterns[$0]==nil}) ?? (source+1)%128;modal=8;softHeld=nil;needsDisplay=true}
    func copyCurrentPattern(to target:Int,confirm:Bool=true){let source=project.selected;guard (0...127).contains(target),target != source else{message="Choose a different destination";return};if project.patterns[target] != nil&&confirm{let alert=NSAlert();alert.messageText="Replace Pattern \(target)?";alert.informativeText="The current Pattern \(source) will replace all its steps and mixer settings.";alert.addButton(withTitle:"Replace");alert.addButton(withTitle:"Cancel");guard alert.runModal() == .alertFirstButtonReturn else{return}};checkpoint();project.patterns[target]=pattern;project.selected=target;row=0;scroll=0;anchor=nil;footer=nil;modal=0;clampTrack();sync();message="Copied P\(source) to P\(target)";needsDisplay=true}
    func patternCopyKey(_ event:NSEvent){let code=event.keyCode,ch=event.charactersIgnoringModifiers?.lowercased() ?? "",d=event.modifierFlags.contains(.shift) ? 10:1;switch code{case 53,48:modal=3;modalField=0;editValue=project.selected;case 36,76:copyCurrentPattern(to:copyTarget);case 123,125:copyTarget=max(0,copyTarget-d);case 124,126:copyTarget=min(127,copyTarget+d);default:if ch=="q"{copyTarget=max(0,copyTarget-d)}else if ch=="e"{copyTarget=min(127,copyTarget+d)}};needsDisplay=true}
    func drawPatternCopy(){let w:CGFloat=470,h:CGFloat=245,x=(bounds.width-w)/2,y=(bounds.height-h)/2;rect(0,0,bounds.width,bounds.height,.black.withAlphaComponent(0.60));rect(x,y,w,h,trackerBackground);border(x,y,w,h,gray(0.65));rect(x,y,w,42,gray(0.27));txt("COPY THIS PATTERN TO",x+15,y+12,14,teal,true);centered("P\(String(format:"%02d",project.selected))  →  P\(String(format:"%02d",copyTarget))",x,y+72,w,25,yellow,true);centered(copyTarget==project.selected ? "Choose a different pattern":project.patterns[copyTarget] == nil ? "Empty destination":"Existing pattern — replacement confirmation",x,y+128,w,12,gray(0.8));centered("Q/E or arrows   Shift ×10   Enter Copy   Esc Back",x,y+h-36,w,11,gray(0.75))}
}
